    {
      "type": "claim",
      "quote": "The detailed plan is binding for the entity submitting the application, as well as for the federal, cantonal and communal authorities.",
      "gist": "The detailed plan is legally binding on the applicant and all relevant authorities."
    },
    {
      "type": "claim",
      "quote": "Appeals against decisions taken by the Federal Council within the scope of the sectoral plan procedure are not possible.",
      "gist": "No appeals are allowed against Federal Council decisions in this procedure."
    },
    {
      "type": "obligation",
      "quote": "the applicant concerned is authorised to develop the transmission line project for the specified corridor and initiate the planning approval process",
      "gist": "After the procedure, the applicant must develop the project and start planning approval."
    },
    {
      "type": "condition",
      "quote": "Under certain circumstances, it is possible to waive the implementation of a sectoral plan procedure.",
      "gist": "Waiver of the sectoral plan procedure is allowed under specific conditions."
    },
    {
      "type": "entity",
      "quote": "SFOE",
      "gist": "Swiss Federal Office of Energy (decides on exemptions)"
    }
  ]
